            'value' => 'a:20:{s:15:"about_header_bg";s:50:"about/3eHZyN8RwDo2GQOSbgzYKSKAzRJQ64ke2nlEcrJw.jpg";s:11:"about_title";s:16:"A propos de nous";s:10:"about_text";s:906:"<p data-path-to-node="0">Fond&eacute;e en 2021, <strong data-path-to-node="0" data-index-in-node="16">CITABIC</strong> est une entreprise de BTP dynamique qui r&eacute;invente les standards de la construction, de la r&eacute;novation et du g&eacute;nie civil &agrave; travers un concept novateur. S&rsquo;appuyant sur l&rsquo;exp&eacute;rience et la r&eacute;activit&eacute; de professionnels qualifi&eacute;s, la soci&eacute;t&eacute; s\'engage &agrave; accompagner ses clients dans tous leurs projets en proposant des solutions <strong data-path-to-node="0" data-index-in-node="345">&laquo; cl&eacute; en main &raquo;</strong> d\'une qualit&eacute; sup&eacute;rieure. Notre cr&eacute;do repose sur un service d\'excellence et une gestion sereine, garantissant ainsi des r&eacute;alisations qui r&eacute;pondent pr&eacute;cis&eacute;ment &agrave; vos besoins et &agrave; vos attentes les plus exigeantes.</p>";s:12:"rounded_text";s:37:"Ensemble, construisons votre avenir !";s:13:"section_image";s:50:"about/TZH0dsVqNUapiHsg4az4Z66TYev8Pp9WJqENVK7V.jpg";s:13:"mission_title";s:13:"Notre mission";s:12:"mission_text";s:158:"<p><strong>CITABIC</strong> articule sa mission autour de la satisfaction client, de la qualite de gestion et d\'une execution structuree de ses processus.</p>";s:12:"why_us_title";s:26:"Pourquoi choisir CITABIC ?";s:11:"why_us_text";s:344:"<p>Expertise BTP certifi&eacute;e <strong data-path-to-node="1" data-index-in-node="29">ISO 9001 &amp; 45001</strong>. Nos &eacute;quipes d&eacute;ploient des solutions innovantes et sur-mesure, garantissant s&eacute;curit&eacute;, transparence (ERP) et durabilit&eacute; pour chacun de vos projets, dans le strict respect de vos exigences.</p>";s:12:"why_us_cards";a:5:{i:0;s:31:"Expertise complète dans le BTP";i:1;s:46:"Engagement envers la qualité et la sécurité";i:2;s:39:"Solutions personnalisées et innovantes";i:3;s:44:"Une équipe de professionnels expérimentés";i:4;s:39:"Infrastructure et technologie de pointe";}s:17:"organigrame_title";s:18:"Notre Organisation";s:11:"organigrame";s:50:"about/9tnBQ840WzezAqyp3v4KjDVVKwh8YTB1rjkUE7Pz.png";s:18:"cartographie_title";s:36:"Cartographie de processus de CITABIC";s:12:"cartographie";s:50:"about/y1DgrAlkrDAQPVFcPlPKWKzKQSsAQkECfuC0CVAP.png";s:17:"contact_form_text";s:28:"Prendre contact avec CITABIC";s:13:"contact_image";s:52:"contact/HKU8tDo9cxFPQaF6hlaThnVT2Jk8QQ7ZPSPzdxpD.png";s:9:"map_embed";s:380:"<iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d994.9369162131916!2d-5.811507772407547!3d35.771870542982874!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0xd0b810011ba8017%3A0xd6bdf01ad993f38f!2sCITABIC!5e0!3m2!1sen!2sma!4v1774108305722!5m2!1sen!2sma" style="border:0;" allowfullscreen="" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe>";s:7:"domains";O:39:"Illuminate\\Database\\Eloquent\\Collection":2:{s:8:"'."\0".'*'."\0".'items";a:3:{i:0;O:24:"App\\Models\\CitabicDomain":33:{s:13:"'."\0".'*'."\0".'connection";s:5:"mysql";s:8:"'."\0".'*'."\0".'table";s:15:"citabic_domains";s:13:"'."\0".'*'."\0".'primaryKey";s:2:"id";s:10:"'."\0".'*'."\0".'keyType";s:3:"int";s:12:"incrementing";b:1;s:7:"'."\0".'*'."\0".'with";a:0:{}s:12:"'."\0".'*'."\0".'withCount";a:0:{}s:19:"preventsLazyLoading";b:0;s:10:"'."\0".'*'."\0".'perPage";i:15;s:6:"exists";b:1;s:18:"wasRecentlyCreated";b:0;s:28:"'."\0".'*'."\0".'escapeWhenCastingToString";b:0;s:13:"'."\0".'*'."\0".'attributes";a:9:{s:2:"id";i:1;s:18:"citabic_profile_id";i:1;s:5:"title";s:12:"Génie civil";s:4:"icon";s:52:"domains/aoAcFNqna3mF4zV5wdUsgU6hS0jAlhHCBEfCGRir.png";s:5:"items";s:113:"["Travaux d\'infrastructure", "VRD", "Autoportant", "Ouvrage d´art", "Assainissement", "Renforcement Structures"]";s:10:"sort_order";i:0;s:12:"translations";s:153:"{"en": {"items": ["Infrastructure works", "VRD"