            'key' => 'laravel-cache-home_page:fr',
            'value' => 'a:9:{s:3:"seo";a:7:{s:5:"title";s:17:"CITABIC | Accueil";s:11:"description";s:84:"CITABIC realise vos projets BTP, genie civil et immobilier avec qualite et securite.";s:8:"keywords";s:44:"citabic, btp, genie civil, immobilier, maroc";s:8:"og_title";s:17:"CITABIC | Accueil";s:14:"og_description";s:84:"CITABIC realise vos projets BTP, genie civil et immobilier avec qualite et securite.";s:8:"og_image";s:82:"http://localhost:8000/storage/contact/HKU8tDo9cxFPQaF6hlaThnVT2Jk8QQ7ZPSPzdxpD.png";s:12:"twitter_card";s:19:"summary_large_image";}s:4:"hero";a:4:{s:8:"subtitle";s:29:"VOTRE VISION, NOTRE EXPERTISE";s:5:"title";s:38:"Ensemble, nous bâtissons votre avenir";s:8:"cta_text";s:9:"Decouvrir";s:11:"circle_text";s:37:"Ensemble, construisons votre avenir !";}s:5:"about";a:7:{s:11:"image_1_url";s:77:"http://localhost:8000/storage/about/8b2b1014-9f28-4a93-bf50-1726d70ac32f.webp";s:11:"image_2_url";s:77:"http://localhost:8000/storage/about/52a4913b-db46-40dd-8c97-7e14f42aee2f.webp";s:11:"image_3_url";s:77:"http://localhost:8000/storage/about/9fc67cae-4e9a-4ccc-80fb-f735adcae07b.webp";s:12:"rounded_text";s:37:"Ensemble, construisons votre avenir !";s:8:"subtitle";s:16:"A propos de nous";s:5:"title";s:24:"Présentation de CITABIC";s:4:"text";s:906:"<p data-path-to-node="0">Fond&eacute;e en 2021, <strong data-path-to-node="0" data-index-in-node="16">CITABIC</strong> est une entreprise de BTP dynamique qui r&eacute;invente les standards de la construction, de la r&eacute;novation et du g&eacute;nie civil &agrave; travers un concept novateur. S&rsquo;appuyant sur l&rsquo;exp&eacute;rience et la r&eacute;activit&eacute; de professionnels qualifi&eacute;s, la soci&eacute;t&eacute; s\'engage &agrave; accompagner ses clients dans tous leurs projets en proposant des solutions <strong data-path-to-node="0" data-index-in-node="345">&laquo; cl&eacute; en main &raquo;</strong> d\'une qualit&eacute; sup&eacute;rieure. Notre cr&eacute;do repose sur un service d\'excellence et une gestion sereine, garantissant ainsi des r&eacute;alisations qui r&eacute;pondent pr&eacute;cis&eacute;ment &agrave; vos besoins et &agrave; vos attentes les plus exigeantes.</p>";}s:7:"domains";a:4:{s:8:"subtitle";s:19:"Domaines d\'activite";s:5:"title";s:37:"Une couverture complete du cycle BTP.";s:4:"text";s:125:"<p>Les activites de CITABIC couvrent le genie civil, le batiment, l\'immobilier et les missions de coordination de projet.</p>";s:5:"items";a:3:{i:0;a:3:{s:5:"title";s:12:"Génie civil";s:5:"items";a:6:{i:0;s:24:"Travaux d\'infrastructure";i:1;s:3:"VRD";i:2;s:11:"Autoportant";i:3;s:14:"Ouvrage d´art";i:4;s:14:"Assainissement";i:5;s:23:"Renforcement Structures";}s:8:"icon_url";s:82:"http://localhost:8000/storage/domains/aoAcFNqna3mF4zV5wdUsgU6hS0jAlhHCBEfCGRir.png";}i:1;a:3:{s:5:"title";s:9:"Bâtiment";s:5:"items";a:6:{i:0;s:26:"Réalisations clé en main";i:1;s:21:"Entreprise générale";i:2;s:11:"Gros œuvre";i:3;s:31:"Rénovations et transformations";i:4;s:66:"Aménagements extérieurs(Dallage Industriel, Béton imprimé …)";i:5;s:8:"Façades";}s:8:"icon_url";s:82:"http://localhost:8000/storage/domains/j1H1u5dsyiblNqROJodZDKnaiBHga5LuYn4gq4I5.png";}i:2;a:3:{s:5:"title";s:10:"Immobilier";s:5:"items";a:3:{i:0;s:40:"Ordonnancement, Pilotage et Coordination";i:1;s:24:"Simulations financières";i:2;s:52:"Acquisition et développement de projets immobiliers";}s:8:"icon_url";s:82:"http://localhost:8000/storage/domains/rC2CNdB4C50jDCsCPhAvWqGv3qcS6EiRFotfR8eA.png";}}}s:3:"why";a:4:{s:9:"image_url";s:77:"http://localhost:8000/storage/about/d7e62eac-a664-46de-9833-4028892d3634.webp";s:8:"subtitle";s:21:"Pourquoi nous choisir";s:5:"title";s:40:"Où la vision rencontre la construction.";s:4:"text";s:234:"Expertise BTP certifiée ISO 9001 & 45001. Nos équipes déploient des solutions innovantes et sur-mesure, garantissant sécurité, transparence (ERP) et durabilité pour chacun de vos projets, dans le strict respect de vos exigences.";}s:6:"values";a:4:{s:8:"subtitle";s:11:"Nos valeurs";s:5:"title";s:18:"Ce que nous defons";s:4:"text";s:0:"";s:10:"empty_text";s:25:"Aucune valeur configuree.";}s:8:"projects";a:4:{s:8:"subtitle";s:11:"Nos projets";s:5:"title";s:31:"Découvrez nos derniers projets";s:4:"text";s:148:"<p>La construction commerciale englobe la conception, le d&eacute;veloppement et la construction de structures destin&eacute;es aux entreprises.</p>";s:5:"items";a:1:{i:0;a:4:{s:4:"slug";s:18:"unite-industrielle";s:5:"title";s:92:"Construction d’une unité industrielle de production de carrelage décoratif traditionnel.";s:6:"client";s:12:"PJLP SARL AU";s:15:"cover_image_url";s:77:"http://localhost:8000/storage/about/d84f913a-f25c-498f-bf89-2ff2cb4f28af.webp";}}}s:7:"contact";a:6:{s:8:"subtitle";s:14:"Contactez-nous";s:10:"form_title";s:28:"Prendre contact avec CITABIC";s:17:"contact_image_url";s:82:"http://localhost:8000/storage/contact/HKU8tDo9cxFPQaF6hlaThnVT2Jk8QQ7ZPSPzdxpD.png";s:9:"map_embed";s:380:"<iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d994.9369162131916!2d-5.811507772407547!3d35.771870542982874!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0xd0b810011ba8017%3A0xd6bdf01ad993f38f!2sCITABIC!5e0!3m2!1sen!2sma!4v1774108305722!5m2!1sen!2sma" style="border:0;" allowfullscreen="" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe>";s:11:"submit_text";s:18:"Envoyer le message";s:19:"message_placeholder";s:13:"Votre message";}s:4:"blog";a:8:{s:8:"subtitle";s:19:"Actualités et blog";s:5:"title";s:27:"Découvrez nos perspectives";s:4:"text";s:245:"<p>La construction commerciale englobe la conception, le d&eacute;veloppement&nbsp; et l\'&eacute;dification de structures strat&eacute;giques d&eacute;di&eacute;es &agrave; la performance des entreprises.<br>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>";s:11:"browse_text";s:17:"Voir tout le blog";s:14:"read_more_text";s:13:"Lire la suite";s:13:"min_read_text";s:14:"min de lecture";s:10:"empty_text";s:36:"Aucun article publie pour le moment.";s:5:"posts";a:1:{i:0;a:6:{s:4:"slug";s:54:"le-maroc-un-chantier-a-ciel-ouvert-vers-lecheance-2030";s:5:"title";s:62:"Le Maroc : Un Chantier à Ciel Ouvert vers l’Échéance 2030";s:7:"excerpt";s:159:"Le BTP au Maroc explose avec la CAN 2025 et le Mondial 2030. 140 mrd DH d\'investissements d\'ici 2025. Un chantier d\'avenir pesant 6% du PIB et 10% de l\'emploi.";s:9:"image_url";s:86:"http://localhost:8000/storage/posts/featured/5964f0bf-1b6c-4b70-a4f4-f33b67e739e7.webp";s:18:"published_at_label";s:14:"March 27, 2026";s:12:"reading_time";i:0;}}}}',
