    'citabic_profiles' => [
        0 => [
            'id' => 1,
            'name' => 'CITABIC',
            'tagline' => 'Ensemble, construisons votre avenir !',
            'full_name' => 'Compagnie Internationale Amenagement Travaux - Batiment Immobilier - Conseil',
            'legal_name' => 'CITABIC',
            'legal_form' => 'SARL a associe unique',
            'capital' => '100 000 MAD',
            'head_office' => '26 Rue Andaloussie, Office Building Anatolia Etage 6 N17, Tanger',
            'ice' => '002789168000063',
            'company_created_at' => '18/04/2021',
            'rc' => '115445',
            'status' => 'En activite',
            'phone' => '+212 611-808226',
            'email' => 'b.benkaddour@citabic.com',
            'hero_video_path' => 'guest/assets/video/citabic-hero.mp4',
            'information_system' => 'CITABIC a implemente une infrastructure informatique de pointe avec l’ERP Odoo pour optimiser la disponibilite, la confidentialite et l’integrite des donnees. Cette architecture traduit sa maturite organisationnelle et sa rigueur professionnelle.',
            'translations' => '{"en": {"intro": "CITABIC is a company whose core business is construction and public works. Responsiveness, experience and dynamism define the way it supports clients across their projects.\\r\\nFounded in 2021, CITABIC brings a new construction concept to the Moroccan market through a turnkey offer covering construction, renovation, civil engineering and consulting.\\r\\nThe company relies on experienced building professionals to deliver quality services with peace of mind, strong execution discipline, and high standards for deadlines, safety and long-term durability.", "mission": "Deliver high-quality construction services and integrated support that fully satisfy clients.\\r\\nProvide expertise and management systems aligned with international standards across every level of the organization.\\r\\nOffer a standardized and systematic range of activities for a turnkey delivery model.\\r\\nGuarantee strong project management quality and long-lasting project durability.", "tagline": "Together we build your future!", "compliance": "Regulatory inspections for equipment including tower cranes and telescopic handlers\\r\\nForklift operator training certification\\r\\nCalibration of equipment such as leveling devices and measuring tools\\r\\nAll-risk construction insurance, CNSS declarations, workplace accident coverage and civil liability insurance\\r\\nTax and CNSS regularity certificates, including 1007 and 1220 attestations", "organization": "General management and strategic development\\r\\nQHS, logistics, purchasing, transport and maintenance\\r\\nOperations, studies/quantity surveying, site execution and control\\r\\nAdministrative and financial management, HR and finance\\r\\nBusiness development and partner coordination", "partnerships": "5 renowned partner architects\\r\\n5 specialized technical design offices\\r\\n4 certified laboratories for analysis and quality testing", "why_choose_us": "Comprehensive construction expertise\\r\\nCommitment to quality and safety\\r\\nTailored and innovative solutions\\r\\nExperienced professional team\\r\\nAdvanced infrastructure and technology", "certifications": "ISO 9001:2015 - Quality management system\\r\\nISO 45001:2018 - Occupational health and safety management system", "market_context": "Economic growth and urbanization continue to drive demand for modern infrastructure and quality housing in Morocco.\\r\\nEnvironmental standards and social expectations require sustainable construction solutions.\\r\\nProjects must comply with international quality and safety standards to ensure long-term asset value.\\r\\nCost and schedule control remains essential in a highly competitive market.\\r\\nAdvanced tools such as BIM and ERP systems are becoming critical for accuracy, transparency and delivery efficiency.", "information_system": "CITABIC has implemented a robust IT infrastructure powered by Odoo ERP to improve data availability, confidentiality and integrity. This architecture reflects organizational maturity and strong operational discipline."}}',
            'created_at' => '2026-03-14 02:38:02',
            'updated_at' => '2026-03-15 12:24:38',
        ],
    ],
    'citabic_references' => [
        0 => [
            'id' => 6,
            'slug' => 'unite-industrielle',
            'title' => 'Construction d’une unité industrielle de production de carrelage décoratif traditionnel.',
            'client' => 'PJLP SARL AU',
            'image' => '/storage/about/46c5c3eb-428e-4798-a5fe-dfe062e237e9.webp',
            'summary' => '<p>PJLP SARL AU est une entreprise sp&eacute;cialis&eacute;e dans la production, la fabrication et la commercialisation de<br>carrelages d&eacute;coratifs sous diverses formes et mat&eacute;riaux. Fond&eacute;e par le cr&eacute;ateur de MOSAIC Factory, elle<br>fait partie d\'un groupe industriel &eacute;tabli en 2002 &agrave; Tanger, qui se consacre &agrave; la fabrication de carreaux, de<br>dalles et d\'&eacute;l&eacute;ments d\'ameublement en mati&egrave;res min&eacute;rales.</p>',
            'description' => '<p>PJLP SARL AU est une entreprise sp&eacute;cialis&eacute;e dans la production, la fabrication et la commercialisation de<br>carrelages d&eacute;coratifs sous diverses formes et mat&eacute;riaux. Fond&eacute;e par le cr&eacute;ateur de MOSAIC Factory, elle<br>fait partie d\'un groupe industriel &eacute;tabli en 2002 &agrave; Tanger, qui se consacre &agrave; la fabrication de carreaux, de<br>dalles et d\'&eacute;l&eacute;ments d\'ameublement en mati&egrave;res min&eacute;rales.</p>',
            'surface' => '6.750 m²',
            'budget' => '25 000 000,00 DH',
            'items' => '[]',
            'blocks' => '[{"type": "coverImage", "content": "/storage/about/d84f913a-f25c-498f-bf89-2ff2cb4f28af.webp"}, {"type": "heroImage", "content": "/storage/about/46c5c3eb-428e-4798-a5fe-dfe062e237e9.webp"}, {"type": "heading", "content": "Construction d’une unité industrielle de production de carrelage décoratif traditionnel.", "content_en": "Construction of an industrial unit for the production of traditional decorative tiles."}, {"type": "text", "content": "<p>PJLP SARL AU est une entreprise sp&eacute;cialis&eacute;e dans la production, la fabrication et la commercialisation de<br>carrelages d&eacute;coratifs sous diverses formes et mat&eacute;riaux. Fond&eacute;e par le cr&eacute;ateur de MOSAIC Factory, elle<br>fait partie d\'un groupe industriel &eacute;tabli en 2002 &agrave; Tanger, qui se consacre &agrave; la fabrication de carreaux, de<br>dalles et d\'&eacute;l&eacute;ments d\'ameublement en mati&egrave;res min&eacute;rales.</p>", "content_en": "<p>PJLP SARL AU is a company specializing in the production, manufacturing, and marketing of decorative tiles in various shapes and materials. Founded by the creator of MOSAIC Factory, it is part of an industrial group established in 2002 in Tangier, dedicated to the manufacture of tiles, slabs, and furniture elements made from mineral materials.</p>"}, {"type": "subheading", "content": "Réalisations", "content_en": "Achievements"}, {"type": "list", "content": "Réalisation G.O une couverture autoportante avec une portée de 36 M\\nRéalisation G.O des planchers en béton précontraint DalleAlvéolées D.A.S ( 12*1,2)\\nRéalisation d’une structure en charpente métallique classique\\nRéalisation G.O des planchers en Hourdis-Poutrelle Jumelée\\nRéalisation des travaux Second d’œuvre (T.C.E)\\nRéalisation des travaux Dallage industrielle, aménagement extérieur, Travaux\\nd’étanchéité, Réseau sous dallage d’assainissement, prestations diverses", "content_en": "Construction of a self-supporting roof with a span of 36 meters.\\nConstruction of prestressed concrete floors using hollow-core slabs (12 x 1.2 m).\\nConstruction of a conventional steel frame structure.\\nConstruction of hollow-core slab floors using twin beams.\\nExecution of finishing work (all trades).\\nExecution of industrial flooring, landscaping, waterproofing, under-slab drainage network, and other services."}, {"type": "gallery", "images": ["/storage/about/e03e1796-1037-4261-9027-54e7d589a99e.webp", "/storage/about/64343865-5e7c-4162-89e6-c528c23751f8.webp"]}]',
            'translations' => '{"en": []}',
            'sort_order' => 6,
            'created_at' => '2026-03-22 19:58:12',
            'updated_at' => '2026-03-23 02:02:52',
        ],
    ],
    'citabic_values' => [
        0 => [
            'id' => 1,
            'citabic_profile_id' => 1,
            'type' => 'values',
            'title' => 'Engagement',
            'text' => '<p>Nous favorisons une culture o&ugrave; nous faisons ce que nous&nbsp;disons et nous respectons nos engagements envers nos&nbsp;clients, nos communaut&eacute;s et entre nous</p>',
            'image' => 'values/433ded46-dfd4-446c-b24a-48a3354545c6.webp',
            'sort_order' => 0,
            'translations' => '{"en": {"text": "<p>We foster a culture where we do what we say and respect our commitments to our customers, our communities, and each other.</p>", "title": "Commitment"}}',
            'created_at' => '2026-03-14 17:55:37',
            'updated_at' => '2026-03-26 01:44:40',
        ],
        1 => [
            'id' => 2,
            'citabic_profile_id' => 1,
            'type' => 'values',
            'title' => 'Qualité',
            'text' => '<p>&Agrave; chaque &eacute;tape de votre chantier, CITABIC s\'assure de la qualit&eacute; du travail qui a &eacute;t&eacute; r&eacute;alis&eacute; par nos corps de m&eacute;tiers exp&eacute;riment&eacute;s</p>',
            'image' => 'values/4a25dd56-c738-4a79-b0fc-1c95af88607f.webp',
            'sort_order' => 0,
            'translations' => '{"en": {"text": "<p>At each stage of your project, CITABIC ensures the quality of the work carried out by our experienced tradespeople.</p>", "title": "Quality"}}',
            'created_at' => '2026-03-26 00:03:21',
            'updated_at' => '2026-03-26 01:44:48',
        ],
        2 => [
            'id' => 3,
            'citabic_profile_id' => 1,
            'type' => 'values',
            'title' => 'Innovation',
            'text' => '<p>Nous estimons que chaque situation est diff&eacute;rente et&nbsp;appelle, en cons&eacute;quence, des solutions adapt&eacute;es. Nous&nbsp;mettons donc tout en &oelig;uvre afin d&rsquo;offrir &agrave; nos clients les&nbsp;solutions op&eacute;rationnelles les plus innovantes</p>',
            'image' => 'values/ffbc7bad-77a6-4361-baf5-1b0f4759de90.webp',
            'sort_order' => 0,
            'translations' => '{"en": {"text": "<p>We believe that every situation is different and&nbsp;therefore requires tailored solutions. We&nbsp;make every effort to offer our clients the most innovative operational solutions.</p>", "title": "Innovation"}}',
            'created_at' => '2026-03-26 00:04:33',
            'updated_at' => '2026-03-26 01:45:09',
        ],
        3 => [
            'id' => 4,
            'citabic_profile_id' => 1,
            'type' => 'values',
            'title' => 'Éthique',
            'text' => '<p>Le respect de l&rsquo;&eacute;thique est la fondation de nos activit&eacute;s. Tout ce que nous faisons est guid&eacute; par une vis&eacute;e morale qui garantit l&rsquo;&eacute;quit&eacute;, le respect et une totale transparence &agrave; toutes les parties prenantes</p>',
            'image' => 'values/ca7b6ccd-c891-4f78-ad8a-acac9a24615a.webp',
            'sort_order' => 0,
            'translations' => '{"en": {"text": "<p>Respect for ethics is the foundation of our activities. Everything we do is guided by a moral compass that guarantees fairness, respect, and complete transparency for all stakeholders.</p>", "title": "Ethics"}}',
            'created_at' => '2026-03-26 00:06:18',
            'updated_at' => '2026-03-26 01:47:03',
        ],
        4 => [
            'id' => 5,
            'citabic_profile_id' => 1,
            'type' => 'values',
            'title' => 'Sécurité',
            'text' => '<p>Conscients des enjeux humains et &eacute;conomiques li&eacute;s &agrave; la s&eacute;curit&eacute;, nous respectons les principes fondamentaux de la pr&eacute;vention sur nos chantiers.</p>',
            'image' => 'values/8617b72c-517d-4c7a-87fc-ddc24d9ed10e.webp',
            'sort_order' => 0,
            'translations' => '{"en": {"text": "<p>Aware of the human and economic stakes linked to safety, we respect the fundamental principles of prevention on our construction sites.</p>", "title": "Security"}}',
            'created_at' => '2026-03-26 00:07:38',
            'updated_at' => '2026-03-26 01:45:39',
        ],
        5 => [
            'id' => 6,
            'citabic_profile_id' => 1,
            'type' => 'values',
            'title' => 'Intégrité',
            'text' => '<p>Nos activit&eacute;s et nos relations professionnelles reposent sur la confiance, l&rsquo;honn&ecirc;tet&eacute; et l&rsquo;ouverture. Nous tenons nos promesses et mettons toujours tout en &oelig;uvre pour agir correctement.&nbsp;</p>',
            'image' => 'values/0ceb5373-f339-4817-b8c8-937bf5ab2de3.webp',
            'sort_order' => 0,
            'translations' => '{"en": {"text": "<p>Our business activities and professional relationships are based on trust, honesty, and openness. We keep our promises and always do our utmost to act correctly.</p>", "title": "Integrity"}}',
            'created_at' => '2026-03-26 00:08:45',
            'updated_at' => '2026-03-26 01:45:48',
        ],
